import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-pandas-working-with-pandas":{"intro":"Pandas is a powerful data manipulation tool developed by Python. It's often used in data analysis and cleaning because it's flexible and easy to use. In this lab, we will learn how to use Pandas to perform basic operations like loading data, creating data frames, accessing data, and performing simple statistics.","steps":[{"title":"Import the Pandas Package","body":["Before you can use Pandas, you need to import it. It's a common practice to import Pandas with the alias pd."],"code":[{"lang":"python","text":"# Importing pandas package\nimport pandas as pd"}]},{"title":"Create a DataFrame","body":["Data in pandas is stored in a DataFrame, which is a 2-dimensional labeled data structure with columns potentially of different types."],"code":[{"lang":"python","text":"# Creating a DataFrame\ndf = pd.DataFrame(\n    {\n        \"Name\": [\n            \"Braund, Mr. Owen Harris\",\n            \"Allen, Mr. William Henry\",\n            \"Bonnell, Miss. Elizabeth\",\n        ],\n        \"Age\": [22, 35, 58],\n        \"Sex\": [\"male\", \"male\", \"female\"],\n    }\n)"}]},{"title":"Select a Column","body":["If you want to work with data in a specific column, you can select it using the column label. The result is a pandas Series."],"code":[{"lang":"python","text":"# Selecting the 'Age' column\ndf[\"Age\"]"}]},{"title":"Perform Basic Statistics","body":["Pandas provides a lot of functionalities to perform statistics. For instance, you can find the maximum value in a column using max().","You can also get a quick overview of the numerical data in a DataFrame using describe()."],"code":[{"lang":"python","text":"# Finding the maximum age\ndf[\"Age\"].max()"},{"lang":"python","text":"# Describing the numerical data\ndf.describe()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Describing the numerical data\ndf.describe()"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-pandas-data-manipulation":{"intro":"This lab will guide you on how to read, write, and manipulate data using Pandas, a powerful data analysis and manipulation library for Python. We will use a dataset from the Titanic shipwreck for this exercise.","steps":[{"title":"Importing Necessary Libraries","body":["First, we need to import the necessary libraries for our task. For this lab, we will only need pandas."],"code":[{"lang":"python","text":"# Importing pandas library\nimport pandas as pd"}]},{"title":"Reading Data From CSV","body":["The next step is to read the data from a CSV file. We will use the read_csv function from pandas to do this."],"code":[{"lang":"python","text":"# Reading data from CSV file\ntitanic = pd.read_csv(\"data/titanic.csv\")"}]},{"title":"Checking the Data","body":["After reading the data, it's always a good idea to check what it looks like. We will display the first few rows of the DataFrame."],"code":[{"lang":"python","text":"# Displaying the first few rows of the DataFrame\ntitanic.head()"}]},{"title":"Checking the Data Types","body":["We can check the data types of each column using the dtypes attribute of the DataFrame."],"code":[{"lang":"python","text":"# Checking the data types of each column\ntitanic.dtypes"}]},{"title":"Writing Data to Excel","body":["You can also write the data to an Excel file using the to_excel method. Let's save our DataFrame to an Excel file."],"code":[{"lang":"python","text":"# Saving DataFrame to an Excel file\ntitanic.to_excel(\"titanic.xlsx\", sheet_name=\"passengers\", index=False)"}]},{"title":"Reading Data From Excel","body":["Reading data from an Excel file is as easy as reading data from a CSV file. We will use the read_excel function from pandas."],"code":[{"lang":"python","text":"# Reading data from an Excel file\ntitanic = pd.read_excel(\"titanic.xlsx\", sheet_name=\"passengers\")"}]},{"title":"Checking DataFrame Information","body":["Checking DataFrame Information","The info method provides a technical summary of a DataFrame. This can be useful to check the data types, number of non-null values, and memory usage."],"code":[{"lang":"python","text":"# Checking DataFrame information\ntitanic.info()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Checking DataFrame information\ntitanic.info()"}],"source":"pandas-dev/pandas · by huduo0812 · BSD 3-Clause"},"labex-pandas-data-selection-in-pandas":{"intro":"In this lab, we are going to learn how to select specific data from a DataFrame using Pandas, a popular data analysis and manipulation library in Python. We will use the Titanic dataset for this tutorial.","steps":[{"title":"Importing the Necessary Libraries and Data","body":["Importing the Necessary Libraries and Data","First, we need to import the Pandas library and the Titanic dataset."],"code":[{"lang":"python","text":"# Import pandas library\nimport pandas as pd\n\n# Load the Titanic dataset\ntitanic = pd.read_csv(\"data/titanic.csv\")\ntitanic.head()"}]},{"title":"Selecting a Single Column","body":["To select a single column, use the square brackets [] with the column name of interest."],"code":[{"lang":"python","text":"# Select the 'Age' column\nages = titanic[\"Age\"]\n\n# Display the first 5 rows\nages.head()"}]},{"title":"Selecting Multiple Columns","body":["To select multiple columns, use a list of column names within the selection brackets []."],"code":[{"lang":"python","text":"# Select the 'Age' and 'Sex' columns\nage_sex = titanic[[\"Age\", \"Sex\"]]\n\n# Display the first 5 rows\nage_sex.head()"}]},{"title":"Filtering Specific Rows","body":["To select rows based on a conditional expression, use the condition inside the selection brackets []."],"code":[{"lang":"python","text":"# Filter rows where 'Age' is greater than 35\nabove_35 = titanic[titanic[\"Age\"] > 35]\n\n# Display the first 5 rows\nabove_35.head()"}]},{"title":"Selecting Specific Rows and Columns","body":["Selecting Specific Rows and Columns","To select both rows and columns in one go, we use the loc or iloc operators."],"code":[{"lang":"python","text":"# Select 'Name' of passengers older than 35\nadult_names = titanic.loc[titanic[\"Age\"] > 35, \"Name\"]\n\n# Display the first 5 rows\nadult_names.head()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Select 'Name' of passengers older than 35\nadult_names = titanic.loc[titanic[\"Age\"] > 35, \"Name\"]\n\n# Display the first 5 rows\nadult_names.head()"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-pandas-plotting-for-air-quality-analysis":{"intro":"In this lab, we will learn how to create plots using Pandas, a powerful data manipulation library in Python. We will use real air quality data for practical illustrations. By the end of this lab, you should be able to use Pandas to create line plots, scatter plots, box plots, and customize your plots.","steps":[{"title":"Import Necessary Libraries","body":["First, we need to import the necessary libraries. We will use Pandas for data manipulation and Matplotlib for data visualization."],"code":[{"lang":"python","text":"# Importing necessary libraries\nimport pandas as pd\nimport matplotlib.pyplot as plt"}]},{"title":"Load the Data","body":["We will use air quality data for this tutorial. The data will be loaded from a CSV file into a Pandas DataFrame."],"code":[{"lang":"python","text":"# Loading the data\nair_quality = pd.read_csv(\"data/air_quality_no2.csv\", index_col=0, parse_dates=True)\nair_quality.head()"}]},{"title":"Create a Line Plot","body":["Pandas creates a line plot for each of the columns with numeric data by default. This gives us a quick visual overview of the data."],"code":[{"lang":"python","text":"# Creating a line plot\nair_quality.plot()\nplt.show()"}]},{"title":"Create a Plot for a Specific Column","body":["Create a Plot for a Specific Column","To plot a specific column, we can use the selection method in combination with the plot method."],"code":[{"lang":"python","text":"# Creating a plot for a specific column\nair_quality[\"station_paris\"].plot()\nplt.show()"}]},{"title":"Create a Scatter Plot","body":["To visually compare the NO2 values measured in London versus Paris, we can create a scatter plot."],"code":[{"lang":"python","text":"# Creating a scatter plot\nair_quality.plot.scatter(x=\"station_london\", y=\"station_paris\", alpha=0.5)\nplt.show()"}]},{"title":"Create a Box Plot","body":["A box plot gives us a good overview of the data distribution. We can create a box plot for our air quality data."],"code":[{"lang":"python","text":"# Creating a box plot\nair_quality.plot.box()\nplt.show()"}]},{"title":"Create Subplots for Each Column","body":["Create Subplots for Each Column","We can create separate subplots for each of the data columns using the subplots argument."],"code":[{"lang":"python","text":"# Creating subplots for each column\naxs = air_quality.plot.area(figsize=(12, 4), subplots=True)\nplt.show()"}]},{"title":"Customize and Save the Plot","body":["We can further customize the plot using Matplotlib's customization options. We can also save the plot to a file."],"code":[{"lang":"python","text":"# Customizing and saving the plot\nfig, axs = plt.subplots(figsize=(12, 4))\nair_quality.plot.area(ax=axs)\naxs.set_ylabel(\"NO$_2$ concentration\")\nfig.savefig(\"no2_concentrations.png\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Customizing and saving the plot\nfig, axs = plt.subplots(figsize=(12, 4))\nair_quality.plot.area(ax=axs)\naxs.set_ylabel(\"NO$_2$ concentration\")\nfig.savefig(\"no2_concentrations.png\")\nplt.show()"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-working-with-columns-in-pandas":{"intro":"In this lab, we will learn how to work with columns in Pandas. We will explore how to create new columns derived from existing ones, apply mathematical and logical operations on columns, rename column labels, and perform column-wise operations using the apply method.","steps":[{"title":"Import Pandas and Load Data","body":["First, we'll import the pandas library and load the air quality data from a CSV file."],"code":[{"lang":"python","text":"# Import pandas library\nimport pandas as pd\n\n# Load air quality data\nair_quality = pd.read_csv(\"data/air_quality_no2.csv\", index_col=0, parse_dates=True)"}]},{"title":"Create a New Column","body":["We'll create a new column, \"london_mg_per_cubic\", by multiplying the \"station_london\" column by a conversion factor."],"code":[{"lang":"python","text":"# Create new column by multiplying \"station_london\" by conversion factor\nair_quality[\"london_mg_per_cubic\"] = air_quality[\"station_london\"] * 1.882"}]},{"title":"Check the Ratio of Values in Two Columns","body":["Check the Ratio of Values in Two Columns","Next, we'll check the ratio of the values in the \"station_paris\" and \"station_antwerp\" columns and save the result in a new column."],"code":[{"lang":"python","text":"# Create new column by dividing \"station_paris\" by \"station_antwerp\"\nair_quality[\"ratio_paris_antwerp\"] = air_quality[\"station_paris\"] / air_quality[\"station_antwerp\"]"}]},{"title":"Rename Column Labels","body":["We'll rename the column labels to match the station identifiers used by OpenAQ."],"code":[{"lang":"python","text":"# Rename column labels\nair_quality_renamed = air_quality.rename(\n    columns={\n        \"station_antwerp\": \"BETR801\",\n        \"station_paris\": \"FR04014\",\n        \"station_london\": \"London Westminster\",\n    }\n)"}]},{"title":"Convert Column Labels to Lowercase","body":["Convert Column Labels to Lowercase","Finally, we'll convert the column labels to lowercase using a function."],"code":[{"lang":"python","text":"# Convert column labels to lowercase\nair_quality_renamed = air_quality_renamed.rename(columns=str.lower)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Convert column labels to lowercase\nair_quality_renamed = air_quality_renamed.rename(columns=str.lower)"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-reshaping-data-with-pandas":{"intro":"In this lab, we will explore how to reshape data in pandas using various functions like sort_values, pivot, pivot_table, and melt. We will work with the Titanic and Air Quality datasets to demonstrate the reshaping techniques.","steps":[{"title":"Import Libraries and Load Data","body":["Import Libraries and Load Data","First, let's import the required libraries and load the datasets."],"code":[{"lang":"python","text":"import pandas as pd\n\n# Load Titanic dataset\ntitanic = pd.read_csv(\"data/titanic.csv\")\n\n# Load Air Quality dataset\nair_quality = pd.read_csv(\"data/air_quality_long.csv\", index_col=\"date.utc\", parse_dates=True)"}]},{"title":"Sort Table Rows","body":["Sort the Titanic dataset according to the age of the passengers and then by cabin class and age in descending order."],"code":[{"lang":"python","text":"# Sort by Age\ntitanic.sort_values(by=\"Age\").head()\n\n# Sort by Pclass and Age in descending order\ntitanic.sort_values(by=['Pclass', 'Age'], ascending=False).head()"}]},{"title":"Convert Long to Wide Table Format","body":["Convert Long to Wide Table Format","We will now convert the long format data of air quality to wide format using the pivot function."],"code":[{"lang":"python","text":"# Filter for no2 data only\nno2 = air_quality[air_quality[\"parameter\"] == \"no2\"]\n\n# Use 2 measurements (head) for each location (groupby)\nno2_subset = no2.sort_index().groupby([\"location\"]).head(2)\n\n# Pivot the data\nno2_subset.pivot(columns=\"location\", values=\"value\")"}]},{"title":"Create a Pivot Table","body":["Create a pivot table to find the mean concentrations for 𝑁𝑂2 and 𝑃𝑀25 in each of the stations."],"code":[{"lang":"python","text":"air_quality.pivot_table(\n    values=\"value\", index=\"location\", columns=\"parameter\", aggfunc=\"mean\"\n)"}]},{"title":"Convert Wide to Long Format","body":["Now, let's convert the wide format data of 𝑁𝑂2 to long format using the melt function."],"code":[{"lang":"python","text":"# Reset index for no2_pivoted\nno2_pivoted = no2.pivot(columns=\"location\", values=\"value\").reset_index()\n\n# Melt the data\nno_2 = no2_pivoted.melt(id_vars=\"date.utc\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Reset index for no2_pivoted\nno2_pivoted = no2.pivot(columns=\"location\", values=\"value\").reset_index()\n\n# Melt the data\nno_2 = no2_pivoted.melt(id_vars=\"date.utc\")"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-handling-time-series-data":{"intro":"This lab will guide you through handling time series data using the Python package, Pandas. We will be working with air quality data for this tutorial. You will learn how to convert strings into datetime objects, perform operations on these datetime objects, resample time series to another frequency, and more.","steps":[{"title":"Import the necessary libraries and load the data","body":["Import the necessary libraries and load the data","First, we need to import the required Python libraries and load the air quality data. The data will be read into a pandas DataFrame, which is a 2-dimensional labeled data structure."],"code":[{"lang":"python","text":"# import necessary libraries\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\n# load the air quality data\nair_quality = pd.read_csv(\"data/air_quality_no2_long.csv\")\n\n# rename the \"date.utc\" column to \"datetime\"\nair_quality = air_quality.rename(columns={\"date.utc\": \"datetime\"})"}]},{"title":"Convert strings to datetime objects","body":["Convert strings to datetime objects","The dates in the \"datetime\" column are currently strings. We want to convert these to datetime objects for easier manipulation."],"code":[{"lang":"python","text":"# convert \"datetime\" column to datetime objects\nair_quality[\"datetime\"] = pd.to_datetime(air_quality[\"datetime\"])"}]},{"title":"Add a new column for the month of the measurement","body":["Add a new column for the month of the measurement","Now, we want to add a new column to our DataFrame that contains only the month of each measurement. This can be achieved using the dt accessor."],"code":[{"lang":"python","text":"# add a new column for the month of each measurement\nair_quality[\"month\"] = air_quality[\"datetime\"].dt.month"}]},{"title":"Calculate the average NO2 concentration for each day of the week","body":["Calculate the average NO2 concentration for each day of the week","We can now calculate the average NO2 concentration for each day of the week at each measurement location. This can be done using the groupby method."],"code":[{"lang":"python","text":"# calculate the average NO2 concentration for each day of the week\naverage_NO2 = air_quality.groupby([air_quality[\"datetime\"].dt.weekday, \"location\"])[\"value\"].mean()"}]},{"title":"Plot the average NO2 values for each hour of the day","body":["Plot the average NO2 values for each hour of the day","We can also plot the average NO2 values for each hour of the day. This can be done using the plot method."],"code":[{"lang":"python","text":"# plot the average NO2 values for each hour of the day\nfig, axs = plt.subplots(figsize=(12, 4))\nair_quality.groupby(air_quality[\"datetime\"].dt.hour)[\"value\"].mean().plot(kind='bar', rot=0, ax=axs)\nplt.xlabel(\"Hour of the day\")\nplt.ylabel(\"$NO_2 (µg/m^3)$\")"}]},{"title":"Resample time series data","body":["The resample method is a powerful way to change the frequency of time series data. Here, we will aggregate the current hourly time series data to the monthly maximum value at each measurement station."],"code":[{"lang":"python","text":"# By pivoting the data, the datetime information became the index of the table.\nno_2 = air_quality.pivot(index=\"datetime\", columns=\"location\", values=\"value\")\nno_2.head()\n\n# Create a plot of the values in the different stations from the 20th of May till the end of 21st of May\nno_2[\"2019-05-20\":\"2019-05-21\"].plot()\n\n# resample time series data\nmonthly_max = no_2.resample(\"M\").max()\nmonthly_max"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# By pivoting the data, the datetime information became the index of the table.\nno_2 = air_quality.pivot(index=\"datetime\", columns=\"location\", values=\"value\")\nno_2.head()\n\n# Create a plot of the values in the different stations from the 20th of May till the end of 21st of May\nno_2[\"2019-05-20\":\"2019-05-21\"].plot()\n\n# resample time series data\nmonthly_max = no_2.resample(\"M\").max()\nmonthly_max"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-pandas-textual-data":{"intro":"In this lab, we will explore how to manipulate textual data using Python's Pandas library. You will learn how to convert string characters to lowercase, extract parts of strings, replace string values and more using various built-in Pandas methods.","steps":[{"title":"Import Necessary Libraries and Data","body":["Import Necessary Libraries and Data","Let's start by importing the Pandas library and loading the data we will use for this tutorial."],"code":[{"lang":"python","text":"# Import necessary libraries\nimport pandas as pd\n\n# Load the data\ntitanic = pd.read_csv(\"data/titanic.csv\")"}]},{"title":"Convert String Characters to Lowercase","body":["Convert String Characters to Lowercase","Next, we will convert all characters in the Name column to lowercase. We'll use the str.lower() method to achieve this."],"code":[{"lang":"python","text":"# Convert all characters in the 'Name' column to lowercase\ntitanic[\"Name\"] = titanic[\"Name\"].str.lower()"}]},{"title":"Extract Surnames from Full Names","body":["Extract Surnames from Full Names","Now, let's create a new column Surname that contains the surname of the passengers. We'll achieve this by extracting the part before the comma in the Name column."],"code":[{"lang":"python","text":"# Split the 'Name' column on comma and extract the first part\ntitanic[\"Surname\"] = titanic[\"Name\"].str.split(\",\").str.get(0)"}]},{"title":"Extract Specific Passenger Data","body":["Extract Specific Passenger Data","Next, let's extract the passenger data for the countesses on board of the Titanic. We'll use the str.contains() method to find rows where the Name column contains the word 'Countess'."],"code":[{"lang":"python","text":"# Find rows where 'Name' contains 'Countess'\ncountesses = titanic[titanic[\"Name\"].str.contains(\"Countess\")]"}]},{"title":"Find the Longest Name","body":["Let's find out which passenger of the Titanic has the longest name. We'll use the str.len() method to get the length of each name, and the idxmax() method to find the index of the longest name."],"code":[{"lang":"python","text":"# Get the length of each name\nname_lengths = titanic[\"Name\"].str.len()\n\n# Find the index of the longest name\nlongest_name_index = name_lengths.idxmax()\n\n# Get the longest name\nlongest_name = titanic.loc[longest_name_index, \"Name\"]"}]},{"title":"Replace Values in a Column","body":["Finally, let's replace the values in the Sex column: 'male' with 'M' and 'female' with 'F'. We'll use the replace() method for this."],"code":[{"lang":"python","text":"# Replace 'male' with 'M' and 'female' with 'F' in the 'Sex' column\ntitanic[\"Sex_short\"] = titanic[\"Sex\"].replace({\"male\": \"M\", \"female\": \"F\"})"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Replace 'male' with 'M' and 'female' with 'F' in the 'Sex' column\ntitanic[\"Sex_short\"] = titanic[\"Sex\"].replace({\"male\": \"M\", \"female\": \"F\"})"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-introduction-to-pandas":{"intro":"In this lab, we will introduce you to the basics of pandas, a powerful data manipulation library in Python. We will guide you through various tasks such as importing pandas, creating and viewing data, data selection, operations and much more.","steps":[{"title":"Importing Pandas and Numpy","body":["First, we need to import pandas and numpy packages. Pandas is a powerful data manipulation library and numpy is used for mathematical operations."],"code":[{"lang":"python","text":"# Importing necessary libraries\nimport numpy as np\nimport pandas as pd"}]},{"title":"Creating Objects","body":["We will create a Series by passing a list of values, and pandas will create a default integer index."],"code":[{"lang":"python","text":"# Creating a pandas series\ns = pd.Series([1, 3, 5, np.nan, 6, 8])\ns"}]},{"title":"Creating Dataframes","body":["We can create a DataFrame by passing a numpy array, with a datetime index and labeled columns."],"code":[{"lang":"python","text":"# Creating a pandas dataframe\ndates = pd.date_range(\"20130101\", periods=6)\ndf = pd.DataFrame(np.random.randn(6, 4), index=dates, columns=list(\"ABCD\"))\ndf"}]},{"title":"Viewing Data","body":["We can view the top and bottom rows of the dataframe using head() and tail() methods respectively."],"code":[{"lang":"python","text":"# Viewing top rows\ndf.head()\n\n# Viewing bottom rows\ndf.tail(3)"}]},{"title":"Data Selection","body":["We can select data using labels or by position."],"code":[{"lang":"python","text":"# Selecting a single column\ndf[\"A\"]\n\n# Selecting via position\ndf.iloc[3]"}]},{"title":"Data Operations","body":["We can perform operations on dataframes like sorting, applying functions, etc."],"code":[{"lang":"python","text":"# Sorting by an axis\ndf.sort_index(axis=1, ascending=False)\n\n# Applying a function to the data\ndf.apply(np.cumsum)"}]},{"title":"Handling Missing Data","body":["Pandas provides methods to handle missing data in the dataframe."],"code":[{"lang":"python","text":"# Filling missing data\ndf.fillna(value=5)\n\n# Getting the boolean mask where values are nan\npd.isna(df)"}]},{"title":"Plotting Data","body":["Pandas uses matplotlib for plotting data."],"code":[{"lang":"python","text":"# Plotting data\ndf.plot()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Saving data to a csv file\ndf.to_csv(\"foo.csv\")\n\n# Loading data from a csv file\npd.read_csv(\"foo.csv\")"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-working-with-nullable-boolean-data":{"intro":"In this lab, we will explore the Nullable Boolean data type, provided by the Pandas library in Python. We will learn how to use this feature in indexing and logical operations, and how it differs from traditional boolean operations due to the presence of 'NA' values.","steps":[{"title":"Importing Necessary Libraries","body":["First, we need to import the necessary libraries to perform the operations."],"code":[{"lang":"python","text":"# Importing the pandas and numpy libraries\nimport pandas as pd\nimport numpy as np"}]},{"title":"Indexing with NA values","body":["Pandas allows indexing with NA values in a boolean array, which are treated as False.","If you want to keep the NA values, you can manually fill them with fillna(True)."],"code":[{"lang":"python","text":"# Creating a pandas Series\ns = pd.Series([1, 2, 3])\n\n# Creating a boolean array with NA values\nmask = pd.array([True, False, pd.NA], dtype=\"boolean\")\n\n# Indexing the series with the boolean array\ns[mask] # NA values are treated as False"},{"lang":"python","text":"# Filling NA values with True and indexing the series\ns[mask.fillna(True)]"}]},{"title":"Kleene logical operations","body":["Pandas implements Kleene Logic (three-value logic) for logical operations like & (and), | (or) and ^ (exclusive-or). This differs from how np.nan behaves in logical operations."],"code":[{"lang":"python","text":"# Demonstrating the difference in 'or' operations between np.nan and NA\npd.Series([True, False, np.nan], dtype=\"object\") | True # np.nan behaves differently\npd.Series([True, False, pd.NA], dtype=\"boolean\") | True # NA follows Kleene logic\n\n# Demonstrating the difference in 'and' operations between np.nan and NA\npd.Series([True, False, np.nan], dtype=\"object\") & True # np.nan behaves differently\npd.Series([True, False, pd.NA], dtype=\"boolean\") & True # NA follows Kleene logic"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Demonstrating the difference in 'or' operations between np.nan and NA\npd.Series([True, False, np.nan], dtype=\"object\") | True # np.nan behaves differently\npd.Series([True, False, pd.NA], dtype=\"boolean\") | True # NA follows Kleene logic\n\n# Demonstrating the difference in 'and' operations between np.nan and NA\npd.Series([True, False, np.nan], dtype=\"object\") & True # np.nan behaves differently\npd.Series([True, False, pd.NA], dtype=\"boolean\") & True # NA follows Kleene logic"}],"source":"pandas-dev/pandas · by huduo0812 · BSD 3-Clause"},"labex-pandas-working-with-data-structures-in-pandas":{"intro":"Pandas is a powerful Python library for data manipulation and analysis. Its fundamental data structures, Series and DataFrame, allow you to store and manipulate structured data. This lab will provide a step-by-step guide on how to work with these data structures, from creation to manipulation and alignment.","steps":[{"title":"Importing Necessary Libraries","body":["Before we start, let's import the necessary libraries. We will need NumPy and pandas for this lab."],"code":[{"lang":"python","text":"# Import necessary libraries\nimport numpy as np\nimport pandas as pd"}]},{"title":"Creating a Series","body":["The first data structure we will look at is a Series, which is a one-dimensional labeled array. It can hold any data type including integers, strings, floating point numbers, and Python objects."],"code":[{"lang":"python","text":"# Create a Series\ns = pd.Series([1, 3, 5, np.nan, 6, 8])"}]},{"title":"Creating a DataFrame","body":["The other fundamental data structure is the DataFrame. It's a two-dimensional labeled data structure with columns of potentially different types."],"code":[{"lang":"python","text":"# Create a DataFrame\ndf = pd.DataFrame(np.random.randn(6, 4), columns=list('ABCD'))"}]},{"title":"Manipulating DataFrame Columns","body":["Manipulating DataFrame Columns","You can perform various operations on DataFrame columns. For example, you can select a column, add a new column, or delete a column."],"code":[{"lang":"python","text":"# Select column A\ndf['A']\n\n# Add a new column E\ndf['E'] = pd.Series(np.random.randn(6), index=df.index)\n\n# Delete column B\ndel df['B']"}]},{"title":"Data Alignment and Arithmetic","body":["Data alignment is an important feature of pandas. When you perform operations on two objects, pandas aligns them by their associated labels."],"code":[{"lang":"python","text":"# Create two DataFrames\ndf1 = pd.DataFrame(np.random.randn(10, 4), columns=['A', 'B', 'C', 'D'])\ndf2 = pd.DataFrame(np.random.randn(7, 3), columns=['A', 'B', 'C'])\n\n# Perform addition operation\nresult = df1 + df2"}]},{"title":"Working with NumPy Functions","body":["Most NumPy functions can be called directly on Series and DataFrame objects, providing a lot of flexibility for data manipulation and analysis."],"code":[{"lang":"python","text":"# Apply the exponential function to a DataFrame\nnp.exp(df)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Apply the exponential function to a DataFrame\nnp.exp(df)"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-handling-duplicate-labels":{"intro":"In this lab, we will learn how to handle duplicate labels in pandas. Pandas is a powerful data manipulation library in Python. Often, we encounter data with duplicate row or column labels, and it's crucial to understand how to detect and handle these duplicates.","steps":[{"title":"Importing Necessary Libraries","body":["First, we need to import the pandas and numpy libraries, which will help us create and manipulate data."],"code":[{"lang":"python","text":"# Importing necessary libraries\nimport pandas as pd\nimport numpy as np"}]},{"title":"Understanding the Consequences of Duplicate Labels","body":["Understanding the Consequences of Duplicate Labels","Duplicate labels can change the behavior of certain operations in pandas. For instance, some methods do not work when duplicates are present."],"code":[{"lang":"python","text":"# Creating a pandas Series with duplicate labels\ns1 = pd.Series([0, 1, 2], index=[\"a\", \"b\", \"b\"])\n\n# Attempting to reindex the Series\ntry:\n    s1.reindex([\"a\", \"b\", \"c\"])\nexcept Exception as e:\n    print(e)"}]},{"title":"Duplicates in Indexing","body":["Next, we will look at how duplicates in indexing can lead to unexpected results."],"code":[{"lang":"python","text":"# Creating a DataFrame with duplicate column labels\ndf1 = pd.DataFrame([[0, 1, 2], [3, 4, 5]], columns=[\"A\", \"A\", \"B\"])\n\n# Indexing 'B' returns a Series\nprint(df1[\"B\"])\n\n# Indexing 'A' returns a DataFrame\nprint(df1[\"A\"])"}]},{"title":"Detecting Duplicate Labels","body":["We can check for duplicate labels using Index.is_unique and Index.duplicated() methods."],"code":[{"lang":"python","text":"# Checking if the index has unique labels\nprint(df1.index.is_unique)\n\n# Checking if the columns have unique labels\nprint(df1.columns.is_unique)\n\n# Detecting duplicate labels in the index\nprint(df1.index.duplicated())"}]},{"title":"Disallowing Duplicate Labels","body":["If needed, we can disallow duplicate labels by using the set_flags(allows_duplicate_labels=False) method."],"code":[{"lang":"python","text":"# Disallowing duplicate labels in a Series\ntry:\n    pd.Series([0, 1, 2], index=[\"a\", \"b\", \"b\"]).set_flags(allows_duplicate_labels=False)\nexcept Exception as e:\n    print(e)\n\n# Disallowing duplicate labels in a DataFrame\ntry:\n    pd.DataFrame([[0, 1, 2], [3, 4, 5]], columns=[\"A\", \"B\", \"C\"]).set_flags(allows_duplicate_labels=False)\nexcept Exception as e:\n    print(e)"}]},{"title":"Checking and Setting the Duplicate Labels Flag","body":["Checking and Setting the Duplicate Labels Flag","Finally, we can check and set the allows_duplicate_labels flag on a DataFrame."],"code":[{"lang":"python","text":"# Creating a DataFrame and setting allows_duplicate_labels to False\ndf = pd.DataFrame({\"A\": [0, 1, 2, 3]}, index=[\"x\", \"y\", \"X\", \"Y\"]).set_flags(allows_duplicate_labels=False)\n\n# Checking the allows_duplicate_labels flag\nprint(df.flags.allows_duplicate_labels)\n\n# Setting allows_duplicate_labels to True\ndf2 = df.set_flags(allows_duplicate_labels=True)\nprint(df2.flags.allows_duplicate_labels)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Creating a DataFrame and setting allows_duplicate_labels to False\ndf = pd.DataFrame({\"A\": [0, 1, 2, 3]}, index=[\"x\", \"y\", \"X\", \"Y\"]).set_flags(allows_duplicate_labels=False)\n\n# Checking the allows_duplicate_labels flag\nprint(df.flags.allows_duplicate_labels)\n\n# Setting allows_duplicate_labels to True\ndf2 = df.set_flags(allows_duplicate_labels=True)\nprint(df2.flags.allows_duplicate_labels)"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-speed-up-pandas-operations":{"intro":"This lab guides you through various techniques to speed up operations on pandas DataFrame using Cython, Numba, and pandas.eval(). These techniques can provide significant speed improvements when working with large datasets.","steps":[{"title":"Setup and Create Sample Data","body":["Before we start, let's import necessary modules and create a sample DataFrame."],"code":[{"lang":"python","text":"# Import necessary modules\nimport pandas as pd\nimport numpy as np\n\n# Create a sample DataFrame\ndf = pd.DataFrame(\n    {\n        \"a\": np.random.randn(1000),\n        \"b\": np.random.randn(1000),\n        \"N\": np.random.randint(100, 1000, (1000)),\n        \"x\": \"x\",\n    }\n)\ndf"}]},{"title":"Implementing Pure Python Function","body":["Implementing Pure Python Function","We will begin by creating a function in pure Python that operates row-wise on the DataFrame."],"code":[{"lang":"python","text":"# Define a function\ndef f(x):\n    return x * (x - 1)\n\n# Define another function that uses the first function\ndef integrate_f(a, b, N):\n       s = 0\n       dx = (b - a) / N\n       for i in range(N):\n           s += f(a + i * dx)\n       return s * dx"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Define a function\ndef f(x):\n    return x * (x - 1)\n\n# Define another function that uses the first function\ndef integrate_f(a, b, N):\n       s = 0\n       dx = (b - a) / N\n       for i in range(N):\n           s += f(a + i * dx)\n       return s * dx"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-pandas-basics-dataframe-memory-and-operation":{"intro":"Welcome to the Pandas Basics Lab! In this lab, we will explore some fundamental aspects of the Pandas library: DataFrame memory usage, handling if/truth statements, using User Defined Function (UDF) methods, dealing with NA values, differences with NumPy, and thread-safety considerations.","steps":[{"title":"Understanding DataFrame Memory Usage","body":["Understanding DataFrame Memory Usage","Pandas provides several methods to understand the memory usage of a DataFrame. The .info() method can be used to see a summary, including memory usage."],"code":[{"lang":"python","text":"import pandas as pd\nimport numpy as np\n\n# Create a DataFrame\ndtypes = [\"int64\", \"float64\", \"datetime64[ns]\", \"timedelta64[ns]\", \"complex128\", \"object\", \"bool\"]\nn = 5000\ndata = {t: np.random.randint(100, size=n).astype(t) for t in dtypes}\ndf = pd.DataFrame(data)\ndf[\"categorical\"] = df[\"object\"].astype(\"category\")\n\n# Display DataFrame info\ndf.info()"}]},{"title":"Using if/truth Statements with Pandas","body":["Using if/truth Statements with Pandas","Pandas does not support using if/truth statements directly due to ambiguity. Instead, use methods like .any(), .all(), or .empty()."],"code":[{"lang":"python","text":"# Check if any value in the Series is True\nif pd.Series([False, True, False]).any():\n    print(\"At least one True value in the Series\")"}]},{"title":"Mutating with User Defined Function (UDF) Methods","body":["Mutating with User Defined Function (UDF) Methods","When using a pandas method that takes a UDF, avoid changing the DataFrame inside the UDF. Instead, make a copy before making changes."],"code":[{"lang":"python","text":"def f(s):\n    s = s.copy()\n    s.pop(\"a\")\n    return s\n\ndf = pd.DataFrame({\"a\": [1, 2, 3], 'b': [4, 5, 6]})\ndf.apply(f, axis=\"columns\")"}]},{"title":"Dealing with NA Values","body":["Pandas provides nullable-integer extension dtypes to represent integers with possibly missing values."],"code":[{"lang":"python","text":"s_int = pd.Series([1, 2, 3, 4, 5], index=list(\"abcde\"), dtype=pd.Int64Dtype())\ns2_int = s_int.reindex([\"a\", \"b\", \"c\", \"f\", \"u\"])"}]},{"title":"Understanding Differences with NumPy","body":["Understanding Differences with NumPy","Pandas and NumPy have slight differences in how they calculate variance. This is important to consider when switching between the two libraries."],"code":[{"lang":"python","text":"# Variance in pandas\nvar_pandas = df.var()\n\n# Variance in NumPy\nvar_numpy = np.var(df.values)"}]},{"title":"Considering Thread-safety in Pandas","body":["Considering Thread-safety in Pandas","Pandas is not 100% thread safe. Be cautious when sharing pandas objects among multiple threads."],"code":[]},{"title":"Handling Byte-ordering Issues","body":["You may encounter byte-ordering issues when dealing with data created on a machine with a different byte order. Convert the data to the native system byte order before passing it to Pandas."],"code":[{"lang":"python","text":"x = np.array(list(range(10)), \">i4\")  # big endian\nnewx = x.byteswap().newbyteorder()  # force native byteorder\ns = pd.Series(newx)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"x = np.array(list(range(10)), \">i4\")  # big endian\nnewx = x.byteswap().newbyteorder()  # force native byteorder\ns = pd.Series(newx)"}],"source":"pandas-dev/pandas · by huduo0812 · BSD 3-Clause"},"labex-pandas-pandas-data-manipulation-fundamentals":{"intro":"This Python Pandas Lab aims to introduce you to the fundamental operations of the pandas library, which is a powerful data manipulation tool in Python. Throughout this lab, you will work with numerous examples and code snippets to solidify your understanding of pandas.","steps":[{"title":"Importing Pandas","body":["Firstly, we need to import the pandas library. This can be done with the following command:"],"code":[{"lang":"python","text":"# Importing pandas library\nimport pandas as pd\nimport numpy as np"}]},{"title":"Creating a DataFrame","body":["Next, we will create a DataFrame, which is a two-dimensional labeled data structure with columns of potentially different types. It is generally the most commonly used pandas object."],"code":[{"lang":"python","text":"# Creating a DataFrame with a dictionary\ndf = pd.DataFrame({'A': [1, 2, 3]})"}]},{"title":"Understanding DataFrames","body":["Now, let's try to understand more about the DataFrame we just created."],"code":[{"lang":"python","text":"# Displaying the DataFrame\nprint(df)\n\n# Info about the DataFrame\ndf.info()"}]},{"title":"Working with Missing Data","body":["Pandas provides various methods for cleaning data and filling missing values."],"code":[{"lang":"python","text":"# Creating a DataFrame with missing values\ndf = pd.DataFrame({'A': [1, 2, np.nan], 'B': [5, np.nan, np.nan], 'C': [1, 2, 3]})\n\n# Filling missing values\ndf.fillna(value=0, inplace=True)"}]},{"title":"Data Visualization","body":["Pandas provides data visualization by allowing integration with the Matplotlib library."],"code":[{"lang":"python","text":"# Importing matplotlib library\nimport matplotlib.pyplot as plt\n\n# Plotting a graph\ndf['A'].plot()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Importing matplotlib library\nimport matplotlib.pyplot as plt\n\n# Plotting a graph\ndf['A'].plot()\nplt.show()"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-working-with-nullable-integers":{"intro":"In this lab, we will explore how to use the nullable integer data type in pandas, which is an efficient way to handle integer data that may contain missing values. We will learn how to construct arrays with this data type, perform operations, and handle missing values effectively.","steps":[{"title":"Constructing Nullable Integer Arrays","body":["Constructing Nullable Integer Arrays","Pandas provides the IntegerArray class for creating arrays of nullable integers. Let's start by creating an IntegerArray.","You can also use the string alias \"Int64\" to specify the data type when creating the array. All NA-like values are replaced with pandas.NA."],"code":[{"lang":"python","text":"# Import necessary libraries\nimport pandas as pd\nimport numpy as np\n\n# Create an IntegerArray with missing values\narr = pd.array([1, 2, None], dtype=pd.Int64Dtype())\n# Output: <IntegerArray>\n# [1, 2, <NA>]\n# Length: 3, dtype: Int64"},{"lang":"python","text":"# Create an IntegerArray using the \"Int64\" string alias\narr = pd.array([1, 2, np.nan], dtype=\"Int64\")\n# Output: <IntegerArray>\n# [1, 2, <NA>]\n# Length: 3, dtype: Int64"}]},{"title":"Storing the IntegerArray in a DataFrame or Series","body":["Storing the IntegerArray in a DataFrame or Series","Once you have created an IntegerArray, you can store it in a DataFrame or Series. Let's create a Series from the IntegerArray we created."],"code":[{"lang":"python","text":"# Create a Series from the IntegerArray\nseries = pd.Series(arr)"}]},{"title":"Performing Operations with Nullable Integer Arrays","body":["Performing Operations with Nullable Integer Arrays","You can perform various operations with nullable integer arrays, such as arithmetic operations, comparisons, and slicing."],"code":[{"lang":"python","text":"# Create a Series with nullable integer type\ns = pd.Series([1, 2, None], dtype=\"Int64\")\n\n# Perform arithmetic operation\ns_plus_one = s + 1 # adds 1 to each element in the series\n\n# Perform comparison\ncomparison = s == 1 # checks if each element in the series is equal to 1\n\n# Perform slicing operation\nsliced = s.iloc[1:3] # selects the second and third elements in the series"}]},{"title":"Handling Missing Values with pandas.NA","body":["Handling Missing Values with pandas.NA","The IntegerArray class uses pandas.NA as its scalar missing value. When you slice a single element that's missing, it will return pandas.NA."],"code":[{"lang":"python","text":"# Create an IntegerArray with a missing value\na = pd.array([1, None], dtype=\"Int64\")\n\n# Slice the second element which is a missing value\nmissing_value = a[1]\n# Output: <NA>"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create an IntegerArray with a missing value\na = pd.array([1, None], dtype=\"Int64\")\n\n# Slice the second element which is a missing value\nmissing_value = a[1]\n# Output: <NA>"}],"source":"pandas-dev/pandas · by huduo0812 · BSD 3-Clause"},"labex-pandas-handling-missing-data":{"intro":"In this lab, we will learn how to handle missing data in pandas, a common issue in data analysis. We'll cover how to identify missing data, fill in missing values, and drop data that's not needed. We will also discuss the experimental NA scalar in pandas that can be used to denote missing values.","steps":[{"title":"Import Necessary Libraries and Create DataFrame","body":["Import Necessary Libraries and Create DataFrame","To start, we need to import the necessary libraries - pandas and NumPy. Then, we'll create a DataFrame with some missing values."],"code":[{"lang":"python","text":"import pandas as pd\nimport numpy as np\n\n# Create a DataFrame with missing values\ndf = pd.DataFrame(\n   np.random.randn(5, 3),\n   index=[\"a\", \"c\", \"e\", \"f\", \"h\"],\n   columns=[\"one\", \"two\", \"three\"],\n)\ndf[\"four\"] = \"bar\"\ndf[\"five\"] = df[\"one\"] > 0\ndf2 = df.reindex([\"a\", \"b\", \"c\", \"d\", \"e\", \"f\", \"g\", \"h\"])"}]},{"title":"Detect Missing Values","body":["Next, we'll use the isna and notna functions to detect missing values."],"code":[{"lang":"python","text":"# Use isna and notna to detect missing values\npd.isna(df2[\"one\"])\ndf2[\"four\"].notna()\ndf2.isna()"}]},{"title":"Insert Missing Data","body":["Here, we'll see how to insert missing values into our data."],"code":[{"lang":"python","text":"# Insert missing values\ns = pd.Series([1., 2., 3.])\ns.loc[0] = None"}]},{"title":"Perform Calculations with Missing Data","body":["Perform Calculations with Missing Data","We'll perform some basic arithmetic and statistical calculations with missing data."],"code":[{"lang":"python","text":"# Perform calculations with missing data\ndf[\"one\"].sum()\ndf.mean(axis=1, numeric_only=True)\ndf.cumsum()"}]},{"title":"Drop Axis Labels with Missing Data","body":["Drop Axis Labels with Missing Data","We'll learn how to exclude labels with missing data using dropna."],"code":[{"lang":"python","text":"df.dropna(axis=0)\ndf.dropna(axis=1)\ndf[\"one\"].dropna()"}]},{"title":"Interpolate Missing Values","body":["We'll use the interpolate function to fill in missing values in a DataFrame."],"code":[{"lang":"python","text":"df = pd.DataFrame(\n   {\n       \"A\": [1, 2.1, np.nan, 4.7, 5.6, 6.8],\n       \"B\": [0.25, np.nan, np.nan, 4, 12.2, 14.4],\n   }\n)\ndf.interpolate()"}]},{"title":"Replace Generic Values","body":["We'll learn how to replace arbitrary values with other values using replace."],"code":[{"lang":"python","text":"ser = pd.Series([0.0, 1.0, 2.0, 3.0, 4.0])\nser.replace(0, 5)"}]},{"title":"Understand NA Scalar to Denote Missing Values","body":["Understand NA Scalar to Denote Missing Values","Finally, we'll discuss the experimental NA scalar in pandas that can be used to denote missing values."],"code":[{"lang":"python","text":"s = pd.Series([1, 2, None], dtype=\"Int64\")\ns"}]}],"commands":[],"reference":[{"path":"reference.py","text":"s = pd.Series([1, 2, None], dtype=\"Int64\")\ns"}],"source":"pandas-dev/pandas · by huduo0812 · BSD 3-Clause"},"labex-pandas-enhance-pandas-with-pyarrow":{"intro":"This lab will guide you through the process of utilizing PyArrow in pandas to extend functionality and improve the performance of various APIs. PyArrow enhances pandas with more extensive data types, missing data support for all data types, IO reader integration, and interoperability with other data frame libraries.","steps":[{"title":"Installing PyArrow","body":[],"code":[{"lang":"shell","text":"# This is a comment\n# Use pip to install PyArrow\n# add ! to the beginning of the line to run the command in the Jupyter notebook\n# !pip install pyarrow\npip install pyarrow"}]},{"title":"Data Structure Integration","body":["PyArrow allows pandas data structures to be directly backed by a PyArrow ChunkedArray, similar to a NumPy array. Here is how to do this:"],"code":[{"lang":"python","text":"# Import pandas\nimport pandas as pd\n\n# Create a pandas Series, Index and DataFrame with PyArrow data type\nser = pd.Series([-1.5, 0.2, None], dtype=\"float32[pyarrow]\")\nidx = pd.Index([True, None], dtype=\"bool[pyarrow]\")\ndf = pd.DataFrame([[1, 2], [3, 4]], dtype=\"uint64[pyarrow]\")"}]},{"title":"Using PyArrow Types with Parameters","body":["Using PyArrow Types with Parameters","For PyArrow types that accept parameters, you can pass in a PyArrow type with those parameters into ArrowDtype to use in the dtype parameter."],"code":[{"lang":"python","text":"# Import PyArrow\nimport pyarrow as pa\n\n# Create a pandas Series with PyArrow list type\nlist_str_type = pa.list_(pa.string())\nser = pd.Series([[\"hello\"], [\"there\"]], dtype=pd.ArrowDtype(list_str_type))"}]},{"title":"Converting PyArrow Array to pandas Data Structures","body":["Converting PyArrow Array to pandas Data Structures","If you have a PyArrow Array or ChunkedArray, you can convert it into pandas data structures like Series, Index or DataFrame."],"code":[{"lang":"python","text":"# Create a PyArrow array\npa_array = pa.array([{\"1\": \"2\"}, {\"10\": \"20\"}, None], type=pa.map_(pa.string(), pa.string()))\n\n# Convert the PyArrow array to a pandas Series\nser = pd.Series(pd.arrays.ArrowExtensionArray(pa_array))"}]},{"title":"PyArrow Operations","body":["PyArrow data structure integration is implemented through pandas' ExtensionArray interface. Supported functionality exists where this interface is integrated within the pandas API."],"code":[{"lang":"python","text":"# Create a pandas Series with PyArrow data type\nser = pd.Series([-1.545, 0.2, None], dtype=\"float32[pyarrow]\")\n\n# Perform various operations\nser.mean()\nser + ser\nser > (ser + 1)\nser.dropna()\nser.isna()\nser.fillna(0)"}]},{"title":"Reading Data with PyArrow","body":["PyArrow provides IO reading functionality that has been integrated into several pandas IO readers."],"code":[{"lang":"python","text":"# Import IO module\nimport io\n\n# Create a StringIO object\ndata = io.StringIO(\"\"\"a,b,c\\n1,2.5,True\\n3,4.5,False\"\"\")\n\n# Read the data into a pandas DataFrame using PyArrow as the engine\ndf = pd.read_csv(data, engine=\"pyarrow\")"}]}],"commands":["pip install pyarrow"],"reference":[{"path":"pyarrow_test_1.py","text":"import unittest\nimport importlib\n\n\nclass PyArrowTestCase(unittest.TestCase):\n    def test_pyarrow_installed(self):\n        try:\n            importlib.import_module(\"pyarrow\")\n            self.assertTrue(True, \"pyarrow 已安装\")\n        except ImportError:\n            self.fail(\"pyarrow 未安装\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()"}],"source":"pandas-dev/pandas · by huduo0812 · BSD 3-Clause"},"labex-pandas-data-reshaping-with-pandas":{"intro":"In data analysis, it is common to encounter datasets that are not arranged in the way we want. Reshaping data refers to the process of changing how data is organized into rows and columns. In this lab, we will explore some of the key methods in Pandas for reshaping data including Pivot, Stack, Unstack, Melt, Cross tabulations, Tiling, Factorizing, and Exploding.","steps":[{"title":"Importing Necessary Libraries and Create DataFrame","body":["Importing Necessary Libraries and Create DataFrame","First, let's import the necessary libraries and create a DataFrame for our examples."],"code":[{"lang":"python","text":"import pandas as pd\nimport numpy as np\n\n# Create DataFrame\nnp.random.seed([3, 1415])\nn = 20\ncols = np.array([\"key\", \"row\", \"item\", \"col\"])\ndf = cols + pd.DataFrame((np.random.randint(5, size=(n, 4)) // [2, 1, 2, 1]).astype(str))\ndf.columns = cols\ndf = df.join(pd.DataFrame(np.random.rand(n, 2).round(2)).add_prefix(\"val\"))"}]},{"title":"Pivoting with Single Aggregations","body":["Pivoting with Single Aggregations","Pivot is one of the key methods for reshaping data in Pandas. It provides a way to transform your data so that you can view it from different angles."],"code":[{"lang":"python","text":"# Pivot df with the mean of val0\ndf.pivot_table(values=\"val0\", index=\"row\", columns=\"col\", aggfunc=\"mean\", fill_value=0)"}]},{"title":"Pivoting with Multiple Aggregations","body":["Pivoting with Multiple Aggregations","We can also perform multiple aggregations in Pivot."],"code":[{"lang":"python","text":"# Pivot df with the mean and sum of val0\ndf.pivot_table(values=\"val0\", index=\"row\", columns=\"col\", aggfunc=[\"mean\", \"sum\"])"}]},{"title":"Cross Tabulations","body":["Cross tabulation is a method to quantitatively analyze the relationship between multiple variables."],"code":[{"lang":"python","text":"# Cross tabulation between row and col\ndf.pivot_table(index=\"row\", columns=\"col\", fill_value=0, aggfunc=\"size\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Cross tabulation between row and col\ndf.pivot_table(index=\"row\", columns=\"col\", fill_value=0, aggfunc=\"size\")"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-scaling-large-datasets":{"intro":"This lab focuses on how to scale data analysis to larger datasets using pandas. It covers methods like loading less data, using efficient data types, chunking, and leveraging other libraries like Dask. It is important to note that pandas is more suited for in-memory analytics and might not be the best tool for very large datasets.","steps":[{"title":"Generate Dataset","body":["The first step is to generate a large dataset for testing. We create a dataset with many columns that can be stored in a parquet file. This step requires pandas and numpy libraries."],"code":[{"lang":"python","text":"import pandas as pd\nimport numpy as np\n\ndef make_timeseries(start=\"2000-01-01\", end=\"2000-12-31\", freq=\"1D\", seed=None):\n    # Function to generate timeseries data\n    index = pd.date_range(start=start, end=end, freq=freq, name=\"timestamp\")\n    n = len(index)\n    state = np.random.RandomState(seed)\n    columns = {\n        \"name\": state.choice([\"Alice\", \"Bob\", \"Charlie\"], size=n),\n        \"id\": state.poisson(1000, size=n),\n        \"x\": state.rand(n) * 2 - 1,\n        \"y\": state.rand(n) * 2 - 1,\n    }\n    df = pd.DataFrame(columns, index=index, columns=sorted(columns))\n    if df.index[-1] == end:\n        df = df.iloc[:-1]\n    return df\n\ntimeseries = [\n    make_timeseries(freq=\"1T\", seed=i).rename(columns=lambda x: f\"{x}_{i}\")\n    for i in range(10)\n]\nts_wide = pd.concat(timeseries, axis=1)\nts_wide.to_parquet(\"timeseries_wide.parquet\")"}]},{"title":"Load Less Data","body":["Instead of loading all the data, we can load only the columns we need. Here, we demonstrate two methods to load less data from the parquet file."],"code":[{"lang":"python","text":"# Option 1: Load all data then filter\ncolumns = [\"id_0\", \"name_0\", \"x_0\", \"y_0\"]\npd.read_parquet(\"timeseries_wide.parquet\")[columns]\n\n# Option 2: Load only the requested columns\npd.read_parquet(\"timeseries_wide.parquet\", columns=columns)"}]},{"title":"Use Efficient Datatypes","body":["Pandas' default data types are not the most memory efficient. This step shows how to use more efficient data types to store larger datasets in memory."],"code":[{"lang":"python","text":"ts = make_timeseries(freq=\"30S\", seed=0)\nts.to_parquet(\"timeseries.parquet\")\nts = pd.read_parquet(\"timeseries.parquet\")\n\n# Convert 'name' column to 'category' type for efficiency\nts2 = ts.copy()\nts2[\"name\"] = ts2[\"name\"].astype(\"category\")\n\n# Downcast numeric columns to their smallest types\nts2[\"id\"] = pd.to_numeric(ts2[\"id\"], downcast=\"unsigned\")\nts2[[\"x\", \"y\"]] = ts2[[\"x\", \"y\"]].apply(pd.to_numeric, downcast=\"float\")"}]},{"title":"Use Chunking","body":["Chunking is a method to split a large problem into smaller problems that can be solved independently. As long as each chunk fits in memory, you can work with datasets that are much larger than memory."],"code":[{"lang":"python","text":"files = pathlib.Path(\"data/timeseries/\").glob(\"ts*.parquet\")\ncounts = pd.Series(dtype=int)\nfor path in files:\n    df = pd.read_parquet(path)\n    counts = counts.add(df[\"name\"].value_counts(), fill_value=0)\ncounts.astype(int)"}]},{"title":"Use Other Libraries","body":["Other libraries like Dask can handle larger-than-memory datasets. Dask provides a pandas-like API and can process data in parallel."],"code":[{"lang":"python","text":"import dask.dataframe as dd\n\nddf = dd.read_parquet(\"data/timeseries/ts*.parquet\", engine=\"pyarrow\")\n\n# Compute value counts using Dask\nddf[\"name\"].value_counts().compute()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import dask.dataframe as dd\n\nddf = dd.read_parquet(\"data/timeseries/ts*.parquet\", engine=\"pyarrow\")\n\n# Compute value counts using Dask\nddf[\"name\"].value_counts().compute()"}],"source":"pandas-dev/pandas · by huduo0812 · BSD 3-Clause"},"labex-pandas-using-sparse-structures-in-pandas":{"intro":"This lab will guide you on how to use sparse data structures in the pandas library. This is useful in scenarios where we have large volumes of data, most of which are similar (like zero or NaN), hence can be represented more efficiently in memory. We will learn about the SparseArray, SparseDtype, sparse accessor, sparse calculation, and interaction with scipy sparse matrices.","steps":[{"title":"Creating a SparseArray","body":["Firstly, we create a sparse array, which is a pandas data structure for efficiently storing an array of sparse values. Sparse values are those that are not stored because they are similar to the majority of the values, hence considered redundant."],"code":[{"lang":"python","text":"# Importing necessary libraries\nimport pandas as pd\nimport numpy as np\n\n# Creating a numpy array with random values\narr = np.random.randn(10)\n\n# Setting some values to NaN\narr[2:-2] = np.nan\n\n# Creating a sparse array with pandas\nts = pd.Series(pd.arrays.SparseArray(arr))\n\n# Output the sparse array\nprint(ts)"}]},{"title":"Checking Memory Efficiency","body":["Next, we will check the memory efficiency of using sparse data structures. We will create a large DataFrame, convert it to sparse, and then compare the memory usage."],"code":[{"lang":"python","text":"# Creating a large DataFrame with random values\ndf = pd.DataFrame(np.random.randn(10000, 4))\n\n# Setting majority of the DataFrame to NaN\ndf.iloc[:9998] = np.nan\n\n# Converting the DataFrame to sparse\nsdf = df.astype(pd.SparseDtype(\"float\", np.nan))\n\n# Checking memory usage of dense vs sparse DataFrame\nprint('dense : {:0.2f} bytes'.format(df.memory_usage().sum() / 1e3))\nprint('sparse: {:0.2f} bytes'.format(sdf.memory_usage().sum() / 1e3))"}]},{"title":"Understanding SparseDtype","body":["The SparseDtype stores the dtype of the non-sparse values and the scalar fill value. We can construct it by passing only a dtype, or also an explicit fill value."],"code":[{"lang":"python","text":"# Creating a SparseDtype\nprint(pd.SparseDtype(np.dtype('datetime64[ns]')))\n\n# Creating a SparseDtype with an explicit fill value\nprint(pd.SparseDtype(np.dtype('datetime64[ns]'), fill_value=pd.Timestamp('2017-01-01')))"}]},{"title":"Using the Sparse Accessor","body":["We can use the .sparse accessor to get attributes and methods specific to sparse data."],"code":[{"lang":"python","text":"# Creating a Series with sparse values\ns = pd.Series([0, 0, 1, 2], dtype=\"Sparse[int]\")\n\n# Using the sparse accessor\nprint(s.sparse.density)\nprint(s.sparse.fill_value)"}]},{"title":"Performing Sparse Calculations","body":["Performing Sparse Calculations","We can apply NumPy ufuncs to SparseArray and get a SparseArray as a result."],"code":[{"lang":"python","text":"# Creating a SparseArray\narr = pd.arrays.SparseArray([1., np.nan, np.nan, -2., np.nan])\n\n# Applying a NumPy ufunc\nprint(np.abs(arr))"}]},{"title":"Converting Between Sparse and Dense","body":["Converting Between Sparse and Dense","We can easily convert data from sparse to dense, and vice versa."],"code":[{"lang":"python","text":"# Converting from sparse to dense\nprint(sdf.sparse.to_dense())\n\n# Converting from dense to sparse\ndense = pd.DataFrame({\"A\": [1, 0, 0, 1]})\ndtype = pd.SparseDtype(int, fill_value=0)\nprint(dense.astype(dtype))"}]},{"title":"Interacting with scipy sparse","body":["Lastly, we can create a DataFrame with sparse values from a scipy sparse matrix, and vice versa."],"code":[{"lang":"python","text":"# Importing necessary libraries\nfrom scipy.sparse import csr_matrix\n\n# Creating a sparse matrix with scipy\narr = np.random.random(size=(1000, 5))\narr[arr < .9] = 0\nsp_arr = csr_matrix(arr)\n\n# Creating a DataFrame from the sparse matrix\nsdf = pd.DataFrame.sparse.from_spmatrix(sp_arr)\n\n# Printing the DataFrame\nprint(sdf.head())\nprint(sdf.dtypes)\n\n# Converting back to sparse matrix\nprint(sdf.sparse.to_coo())"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Importing necessary libraries\nfrom scipy.sparse import csr_matrix\n\n# Creating a sparse matrix with scipy\narr = np.random.random(size=(1000, 5))\narr[arr < .9] = 0\nsp_arr = csr_matrix(arr)\n\n# Creating a DataFrame from the sparse matrix\nsdf = pd.DataFrame.sparse.from_spmatrix(sp_arr)\n\n# Printing the DataFrame\nprint(sdf.head())\nprint(sdf.dtypes)\n\n# Converting back to sparse matrix\nprint(sdf.sparse.to_coo())"}],"source":"pandas-dev/pandas · by huduo0812 · BSD 3-Clause"},"labex-pandas-text-data-handling-in-pandas":{"intro":"This lab introduces how to handle text data in pandas. We will learn how to store text data, use string methods for data preprocessing and transformation, and extract substrings using regular expressions. We will also learn how to create dummy variables for machine learning algorithms.","steps":[{"title":"Store Text Data","body":["In pandas, you can store text data in two ways: using an object dtype NumPy array or a StringDtype extension type. We recommend using StringDtype because it's safer and more specific than the generic object dtype."],"code":[{"lang":"python","text":"import pandas as pd\n\n# create a series with `object` dtype\ns1 = pd.Series([\"a\", \"b\", \"c\"], dtype=\"object\")\n\n# create a series with `StringDtype`\ns2 = pd.Series([\"a\", \"b\", \"c\"], dtype=\"string\")"}]},{"title":"Use String Methods","body":["Pandas provides a suite of string processing methods that make it easy to operate on string data. These methods automatically exclude missing/NA values."],"code":[{"lang":"python","text":"s = pd.Series(\n    [\"A\", \"B\", \"C\", \"Aaba\", \"Baca\", np.nan, \"CABA\", \"dog\", \"cat\"], dtype=\"string\"\n)\n\n# convert to lowercase\ns.str.lower()\n\n# convert to uppercase\ns.str.upper()\n\n# calculate the length of each string\ns.str.len()"}]},{"title":"Extract Substrings","body":["You can extract substrings using regular expressions. The extract method accepts a regular expression with at least one capture group."],"code":[{"lang":"python","text":"# extract the first digit from each string\ns = pd.Series([\"a1\", \"b2\", \"c3\"], dtype=\"string\")\ns.str.extract(r\"(\\d)\", expand=False)"}]},{"title":"Test for Strings","body":["You can check whether elements contain or match a pattern using the contains and match methods respectively."],"code":[{"lang":"python","text":"# check if each string contains the pattern \"a\"\ns.str.contains(\"a\", na=False)\n\n# check if each string matches the pattern \"a\"\ns.str.match(\"a\", na=False)"}]},{"title":"Create Dummy Variables","body":["You can create dummy variables from string data using the get_dummies method."],"code":[{"lang":"python","text":"# create dummy variables\ns = pd.Series([\"a\", \"a|b\", np.nan, \"a|c\"], dtype=\"string\")\ns.str.get_dummies(sep=\"|\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# create dummy variables\ns = pd.Series([\"a\", \"a|b\", np.nan, \"a|c\"], dtype=\"string\")\ns.str.get_dummies(sep=\"|\")"}],"source":"pandas-dev/pandas · BSD 3-Clause"},"labex-pandas-working-with-time-deltas":{"intro":"This lab guides you through the process of working with time deltas in Python using the pandas library. A time delta represents a duration or difference in time. We will explore different ways to construct, manipulate, and operate on time deltas.","steps":[{"title":"Import the Required Libraries","body":["First, we need to import the necessary libraries. In this case, we will be using pandas and numpy."],"code":[{"lang":"python","text":"# Import the required libraries\nimport pandas as pd\nimport numpy as np\nimport datetime"}]},{"title":"Construct a Timedelta","body":["Let's create a timedelta object, which represents a duration or difference in time."],"code":[{"lang":"python","text":"# Construct a timedelta object\npd.Timedelta(\"1 days 2 hours\")"}]},{"title":"Convert to Timedelta","body":["You can convert a scalar, array, list, or series from a recognized timedelta format into a timedelta type."],"code":[{"lang":"python","text":"# Convert a string to a timedelta\npd.to_timedelta(\"1 days 06:05:01.00003\")"}]},{"title":"Perform Operations","body":["You can perform mathematical operations on timedeltas."],"code":[{"lang":"python","text":"# Subtract two timedeltas\ns = pd.Series(pd.date_range(\"2012-1-1\", periods=3, freq=\"D\"))\ns - s.max()"}]},{"title":"Access Attributes","body":["You can access various components of the timedelta directly."],"code":[{"lang":"python","text":"# Access the days attribute of a timedelta\ntds = pd.Timedelta(\"31 days 5 min 3 sec\")\ntds.days"}]},{"title":"Convert to ISO 8601 Duration","body":["You can convert a timedelta to an ISO 8601 Duration string."],"code":[{"lang":"python","text":"# Convert a timedelta to an ISO 8601 Duration string\npd.Timedelta(days=6, minutes=50, seconds=3, milliseconds=10, microseconds=10, nanoseconds=12).isoformat()"}]},{"title":"Create a Timedelta Index","body":["You can generate an index with time deltas."],"code":[{"lang":"python","text":"# Generate a timedelta index\npd.TimedeltaIndex([\"1 days\", \"1 days, 00:00:05\", np.timedelta64(2, \"D\"), datetime.timedelta(days=2, seconds=2)])"}]},{"title":"Use the Timedelta Index","body":["You can use the timedelta index as the index of pandas objects."],"code":[{"lang":"python","text":"# Use the timedelta index as the index of a pandas series\ns = pd.Series(np.arange(100), index=pd.timedelta_range(\"1 days\", periods=100, freq=\"h\"))"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Resample data with a timedelta index\ns.resample(\"D\").mean()"}],"source":"pandas-dev/pandas · BSD 3-Clause"}};
